package com.acely.document;
import com.acely.ai.GeminiService; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
@Service public class DocumentService { private final DocumentRepository repo; private final TextExtractor extractor; private final GeminiService gemini; private final ObjectMapper mapper=new ObjectMapper(); public DocumentService(DocumentRepository r,TextExtractor e,GeminiService g){repo=r;extractor=e;gemini=g;}
 @Transactional public Document upload(MultipartFile file) throws Exception { if(file==null||file.isEmpty()) throw new IllegalArgumentException("Please choose a non-empty file."); String name=Optional.ofNullable(file.getOriginalFilename()).orElse("material"); if(!name.matches("(?i).+\\.(pdf|docx|pptx|txt)$")) throw new IllegalArgumentException("Supported files are PDF, DOCX, PPTX, and TXT."); Document d=new Document(); d.fileName=name; d.fileType=name.substring(name.lastIndexOf('.')+1).toUpperCase(); d.fileSize=file.getSize(); d.status=Document.Status.PROCESSING; d=repo.save(d); try { d.extractedText=extractor.extract(file).replaceAll("\\s+"," ").trim(); if(d.extractedText.length()<20) throw new IllegalArgumentException("Unable to process this document. Please make sure it contains readable text."); d.status=Document.Status.UPLOADED; return repo.save(d); } catch(Exception ex) { d.status=Document.Status.FAILED; repo.save(d); throw ex; } }
 @Transactional public void generateAll(long id){ generate(id,"notes"); generate(id,"flashcards"); generate(id,"quiz"); generate(id,"mindmap"); Document d=get(id);d.status=Document.Status.READY;repo.save(d); }
 @Transactional public JsonNode generate(long id,String type){ Document d=get(id); if(d.extractedText==null||d.extractedText.isBlank()) throw new IllegalArgumentException("This document has no readable text."); d.status=Document.Status.PROCESSING; repo.save(d); String schema=switch(type){ case "notes" -> "Return JSON only: {title,overview,keyPoints:[string],definitions:[{term,meaning}],examTips:[string]}."; case "flashcards" -> "Return JSON only: {flashcards:[{question,answer,difficulty}]}. Create 10-20 cards."; case "quiz" -> "Return JSON only: {questions:[{question,options:[string,string,string,string],correctAnswer,explanation,difficulty}]}. Create exactly 10 questions."; case "mindmap" -> "Return JSON only: {topic,nodes:[{id,label,type}],edges:[{source,target}]}."; default -> throw new IllegalArgumentException("Unknown resource type.");}; JsonNode result=gemini.generate("You are an educational assistant. Analyze ONLY the supplied study material. Do not invent unrelated facts. "+schema,d.extractedText); validate(type,result); try { String json=mapper.writeValueAsString(result); switch(type){case "notes"->d.notesJson=json;case "flashcards"->d.flashcardsJson=json;case "quiz"->d.quizJson=json;case "mindmap"->d.mindMapJson=json;} d.status=Document.Status.READY;repo.save(d);return result;}catch(Exception e){throw new IllegalStateException("Unable to save generated content.");} }
 public JsonNode resource(long id,String type){Document d=get(id);String json=switch(type){case "notes"->d.notesJson;case "flashcards"->d.flashcardsJson;case "quiz"->d.quizJson;case "mindmap"->d.mindMapJson;default->null;};try{return json==null?null:mapper.readTree(json);}catch(Exception e){throw new IllegalStateException("Saved content is invalid.");}}
 public Document get(long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Document not found."));} public List<Document> all(){return repo.findAll();} public void delete(long id){repo.delete(get(id));}
 private void validate(String type,JsonNode n){boolean ok=switch(type){case "notes"->n.hasNonNull("overview")&&n.has("keyPoints");case "flashcards"->n.path("flashcards").isArray();case "quiz"->n.path("questions").isArray();case "mindmap"->n.hasNonNull("topic")&&n.path("nodes").isArray()&&n.path("edges").isArray();default->false;};if(!ok)throw new IllegalArgumentException("AI returned incomplete content. Please try again.");}
}
